public sealed class CheckoutService(
    [FromKeyedServices("stripe")] IPaymentGateway stripe,
    [FromKeyedServices("paypal")] IPaymentGateway paypal,
    IOrderRepository orders)
{
    public async Task<PaymentResult> PayAsync(
        Guid orderId, string provider, CancellationToken ct)
    {
        var gateway = provider switch
        {
            "stripe" => stripe,
            "paypal" => paypal,
            _ => throw new ArgumentException($"Unknown provider {provider}")
        };
        var order = await orders.GetByIdAsync(orderId, ct);
        return await gateway.ChargeAsync(order.Total, ct);
    }
}

app.MapPost("/pay/{provider}", async (
    string provider,
    PaymentRequest request,
    [FromKeyedServices("stripe")] IPaymentGateway stripe,
    [FromKeyedServices("paypal")] IPaymentGateway paypal) =>
{
    var gateway = provider switch
    {
        "stripe" => stripe,
        "paypal" => paypal,
        _ => throw new BadHttpRequestException("Unknown provider")
    };
    return Results.Ok(await gateway.ChargeAsync(request.Amount));
});

public sealed class PaymentRouter(IServiceProvider sp)
{
    public IPaymentGateway Resolve(string provider) =>
        sp.GetRequiredKeyedService<IPaymentGateway>(provider);
}

// List all keyed registrations (diagnostics / admin endpoint)
public sealed class ProviderRegistry([FromKeyedServices] IServiceProvider sp)
{
    // GetKeyedServices<T>() returns all keyed instances
    public IEnumerable<string> ListProviders(IServiceProvider provider)
    {
        // Use service descriptor inspection or maintain a registry
        return ["stripe", "paypal"];
    }
}

